insert into questions (question_text, options, correct_index, category) values
('5S là gì ?', '["Là phương pháp làm việc an toàn và đạt hiệu suất cao.", "Là phương pháp làm việc sạch sẽ, gọn gàng, ngăn nắp.", "Là phương pháp cơ bản cải thiện môi trường làm việc."]', 2, '5S'),
('Thứ tự đúng của 5S', '["Sắp xếp – Sạch sẽ - Sàng lọc – Sẵn sàng – Săn sóc.", "Sàng lọc – Săn sóc – Sạch sẽ - Sắp xếp – Sẵn sàng .", "Sàng lọc – Sắp xếp – Sạch sẽ - Săn sóc – Sẵn sàng.", "Sàng lọc – Sắp xếp – Sạch sẽ - Sẵn sàng – Săn sóc."]', 2, '5S'),
('Nhiệm vụ của S4: Săn sóc', '["Duy trì S1 – S2 – S3.", "Hình thành các tiêu chuẩn và qui định về 5S.", "Thực hiện việc giám sát, kiểm tra sự tuân thủ.", "Cả 3 câu trên đều đúng"]', 3, '5S'),
('4 Dễ trong 5S : Dễ …. – Dễ thấy – Dễ lấy – Dễ …..', '["Hiểu – Trả.", "Tìm – Trả.", "Sử dụng – Tìm.", "Tìm – Sử dụng."]', 1, '5S'),
('Mục tiêu chính của 5S:', '["Tạo môi trường làm việc sạch sẽ thông thoáng.", "Xây dựng thói quen tốt, hình thành văn hóa 5 S và cải tiến liên tục.", "Giảm lãng phí và nâng cao hiệu suất."]', 1, '5S'),
('Những cản trở gây khó khăn cho việc thực hiện S3 (Sạch sẽ) :', '["Dụng cụ vệ sinh không đúng chuẩn và thiếu.", "Không phân công khu vực, thiếu hướng dẫn, thiếu kiểm tra.", "Nhân viên thiếu hợp tác và lười vệ sinh.", "Các câu trên đều đúng."]', 3, '5S'),
('Mục đích của Tiêu Chuẩn Hóa trong 5S là:', '["Quy định cách làm tốt nhất tại thời điểm hiện tại.", "Xác lập trạng thái hiện tại.", "Cơ sở để kiểm tra, đánh giá 5S.", "Chỉ để đối phó và mang tính hình thức.", "Câu a,b,c đều đúng"]', 4, '5S'),
('Trực Quan Hóa trong 5S là:', '["Đọc là hiểu.", "Nhìn là hiểu .", "Những biển báo đẹp mắt.", "Những thông báo chi tiết kèm hình ảnh."]', 1, '5S'),
('Tiêu Chuẩn Hóa trong 5S cần những đặc điểm:', '["Càng đơn giản càng tốt.", "Trực quan hóa.", "Đặt tại vị trí dễ nhìn thấy.", "Cả 3 câu trên đều đúng."]', 3, '5S'),
('Để duy trì được 5S các điều cơ bản sau đây cần thực hiện:', '["Kỷ luật nghiêm khắc người vi phạm.", "Quản lý phải đi giám sát thường xuyên.", "Thực hiện tốt S4.", "Quản lý phải làm gương và hỗ trợ thực thi.", "Câu c và d đúng."]', 4, '5S'),
('Mục đích của S5 – Sẵn Sàng là:', '["Tạo thói quen tốt cho người quản lý.", "Tạo thói quen tốt cho tất cả mọi người.", "Duy trì việc cải tiến liên tục tại các vị trí quan trọng.", "Liên tục cải tiến khắp mọi nơi.", "Câu a và c không đúng."]', 4, '5S'),
('Khi triển khai thực hiện 5S chúng ta cần:', '["Thực hiện cùng lúc từ S1-S5.", "Thực hiện S1, S2, S3 trước, kế đến là S4,S5.", "Thực hiện S1,S2,S3, S4; khi nào xong mới đến S5.", "Thực hiện S nào trước cũng được."]', 1, '5S'),
('Bước nào trong 5S liên quan đến việc loại bỏ những vật dụng không cần thiết tại nơi làm việc?', '["Seiri (Sàng lọc)", "Seiton (Sắp xếp)", "Seiso (Sạch sẽ)", "Shitsuke (Sẵn sàng)"]', 0, '5S'),
('Lợi ích chính của việc duy trì sạch sẽ (Seiso) trong nơi làm việc là gì?', '["Tăng tính thẩm mỹ.", "Giảm thiểu tai nạn lao động.", "Cải thiện tinh thần nhân viên.", "Tất cả các đáp án trên"]', 3, '5S'),
('Mục đích chính của bước Sàng lọc (Seiri) trong 5S là gì?', '["Loại bỏ các vật dụng không cần thiết", "Phân loại các công cụ theo màu sắc.", "Đánh dấu các vị trí làm việc.", "Lưu trữ hồ sơ tài liệu."]', 0, '5S'),
('Sắp xếp (Seiton) trong 5S liên quan đến điều gì?', '["Bố trí không gian làm việc sao cho hợp lý và thuận tiện", "Đặt các vật dụng ngẫu nhiên vào các vị trí trống.", "Sắp xếp hồ sơ theo thứ tự alphabet .", "Chỉ sắp xếp các công cụ quan trọng."]', 0, '5S'),
('Săn sóc (Seiketsu) trong 5S có nghĩa là gì?', '["Tiêu chuẩn hóa các quy trình làm việc", "Chăm sóc cây cảnh tại nơi làm việc.", "Kiểm tra chất lượng sản phẩm.", "Tạo các khu vực nghỉ ngơi cho nhân viên."]', 0, '5S'),
('Để thực hiện Sẵn sàng (Shitsuke), tổ chức cần làm gì?', '["Đào tạo nhân viên về các nguyên tắc 5S", "Thường xuyên đánh giá và cải tiến quy trình.", "Tạo ra các quy định và chuẩn mực rõ ràng.", "Áp dụng hình phạt cho ai không thực hiện đúng."]', 0, '5S'),
('Trong bước Seiton (Sắp xếp), nguyên tắc nào dưới đây là quan trọng nhất?', '["Để mọi vật dụng vào cùng một nơi", "Để các vật dụng dễ dàng tìm thấy và sử dụng.", "Để mọi vật dụng đều phải có màu sắc giống nhau.", "Để tạo ra một môi trường làm việc đẹp mắt."]', 1, '5S'),
('Khi áp dụng 5S, điều gì sau đây là không đúng?', '["Sáng tạo các cách làm việc mới không theo tiêu chuẩn 5S", "Thực hiện định kỳ kiểm tra 5S tại nơi làm việc.", "Giữ cho nơi làm việc sạch sẽ và gọn gàng.", "Khuyến khích nhân viên tham gia vào quá trình 5S."]', 0, '5S'),
('Để phát triển thói quen Shitsuke (Sẵn sàng), công ty nên:', '["Chỉ thực hiện 5S một lần.", "Tổ chức các buổi đào tạo và nhắc nhở thường xuyên", "Khuyến khích nhân viên sáng tạo tự do.", "Không cần theo dõi quá trình thực hiện 5S."]', 1, '5S'),
('Ai là người chịu trách nhiệm chính trong việc duy trì 5S tại nơi làm việc?', '["Chỉ quản lý cấp cao.", "Tất cả nhân viên.", "Chỉ nhân viên bảo trì.", "Nhân viên mới."]', 1, '5S');